\begin{aligned}
6\cos(\omega_0 t+\pi/6) &= 3\left(e^{j(\omega_0 t+\pi/6)}+e^{-j(\omega_0 t+\pi/6)}\right) \\
c_1 &= \frac{1}{T}\int_0^T 6\cos(\omega_0 t+\pi/6)e^{-j\omega_0 t}\,dt \\
&= \frac{1}{T}\int_0^T 3\left(e^{j(\omega_0 t+\pi/6)}+e^{-j(\omega_0 t+\pi/6)}\right)e^{-j\omega_0 t}\,dt \\
&= 3e^{j\pi/6}
\end{aligned}

\begin{aligned}
-8\cos(\omega_0 t-\pi/4) &= -4\left(e^{j(\omega_0 t-\pi/4)}+e^{-j(\omega_0 t-\pi/4)}\right) \\
c_1 &= \frac{1}{T}\int_0^T -8\cos(\omega_0 t-\pi/4)e^{-j\omega_0 t}\,dt \\
&= \frac{1}{T}\int_0^T -4\left(e^{j(\omega_0 t-\pi/4)}+e^{-j(\omega_0 t-\pi/4)}\right)e^{-j\omega_0 t}\,dt \\
&= -4e^{-j\pi/4}
\end{aligned}
